import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.9yf7n3zg.js";const s="/guide/media/formats-sources.webp",u=JSON.parse('{"title":"Files Leathercase reads","description":"","frontmatter":{},"headers":[],"relativePath":"reference/formats.md","filePath":"reference/formats.md","lastUpdated":1792112190000}'),d={name:"reference/formats.md"};function i(n,e,c,h,l,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="files-leathercase-reads" tabindex="-1">Files Leathercase reads <a class="header-anchor" href="#files-leathercase-reads" aria-label="Permalink to &quot;Files Leathercase reads&quot;">​</a></h1><p>This page lists the files Leathercase reads, how it turns each kind into scenes, chapters and parts, and what it leaves alone. Every file here is read only. Leathercase never saves over a manuscript, never converts it and never moves it; it writes only its own files, which are listed in <a href="/guide/reference/suite-files">Files Leathercase writes</a>.</p><h2 id="the-short-list" tabindex="-1">The short list <a class="header-anchor" href="#the-short-list" aria-label="Permalink to &quot;The short list&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th>Files</th><th>Read as</th><th>Opens in, from the manuscript</th></tr></thead><tbody><tr><td>Markdown</td><td><code>.md</code></td><td>Notes: front matter, headings, prose, links, comments</td><td>Obsidian, iA Writer, Typora, Visual Studio Code, Sublime Text, Zed, or your default app</td></tr><tr><td>Word</td><td><code>.docx</code></td><td>Notes: headings from the paragraph styles, prose, emphasis, quotes</td><td>Microsoft Word, LibreOffice Writer, or your default app</td></tr><tr><td>Scrivener</td><td>a <code>.scriv</code> project (Scrivener 3 and 2)</td><td>One note per text item in the binder, in binder order</td><td>Scrivener</td></tr><tr><td>Fountain</td><td><code>.fountain</code></td><td>A screenplay: sections and sluglines as scenes, cues as the cast, sluglines as places</td><td>Visual Studio Code, Sublime Text, Zed, Highland, Fade In, or your default app</td></tr></tbody></table><p>A story can mix them. A folder of Word chapters with Markdown character notes is one story; so is a Fountain script with a Markdown bible beside it.</p><p>Everything else in the folder is listed and left alone: images, PDFs, spreadsheets, <code>.txt</code>, <code>.rtf</code> files outside a Scrivener project, <code>.odt</code>, the older Word <code>.doc</code>. They never become scenes and Leathercase never opens them. <strong>How this story is read</strong> counts them under <strong>Notes left out</strong> as &quot;other files no pattern reads, such as images&quot;.</p><p><img src="'+s+'" alt="Settings at Sources, listing each story of the sample home with the format it is read from and the app its passages open in" width="860" height="670" loading="lazy"></p><p><em>Settings, Sources: each story&#39;s source, read only, and the app its passages open in.</em></p><h2 id="what-decides-which-files-belong-to-a-story" tabindex="-1">What decides which files belong to a story <a class="header-anchor" href="#what-decides-which-files-belong-to-a-story" aria-label="Permalink to &quot;What decides which files belong to a story&quot;">​</a></h2><p>A story is a folder in your writing home, declared once in Leathercase (see <a href="/guide/guide/declare-a-story">Declaring a story</a>). Three things decide which of the folder&#39;s files it reads.</p><ol><li><strong>Include patterns.</strong> A new story reads <code>**/*.md</code>, <code>**/*.fountain</code> and <code>**/*.docx</code>: every Markdown, Fountain and Word file under its folder, at any depth. A Scrivener project&#39;s texts arrive as Markdown, so the same patterns take them in.</li><li><strong>Ignore patterns.</strong> A pattern such as <code>_Work/**</code> in Story settings leaves a folder out of every view. The Lamp at Ferrol leaves its <code>_Work/</code> folder of research and review notes out this way.</li><li><strong>What each file is.</strong> Only the files declared as the story&#39;s prose make scenes. Character, place, item, faction and event notes are the cast and the world; plans, records, work notes, research and scraps are notes about the story. A file nothing claims is unsorted, and Leathercase asks about it instead of guessing. <a href="/guide/guide/how-a-story-is-read">How a story is read</a> explains the rules.</li></ol><p>Some files are never read as the story, whatever the patterns say:</p><table tabindex="0"><thead><tr><th>Left out</th><th>Why</th></tr></thead><tbody><tr><td>Hidden files and folders, such as <code>.obsidian</code>, <code>.git</code>, <code>.trash</code></td><td>They hold another app&#39;s own state, never prose</td></tr><tr><td>Any <code>suite/</code> folder holding Leathercase&#39;s files, <code>Suite.md</code>, the home&#39;s <code>Writer/</code> cards folder</td><td>They are Leathercase&#39;s own files</td></tr><tr><td>The story&#39;s note: a note whose front matter says <code>story: true</code> or a <code>writing-target</code></td><td>It carries the story&#39;s settings, so it is read for those, not as a scene</td></tr><tr><td>A note whose front matter says <code>creative-writer: false</code></td><td>The Obsidian plugin&#39;s opt-out, still honoured</td></tr><tr><td>Notes the Obsidian plugin wrote for itself (front matter keys that start with <code>creative-writer-</code>)</td><td>They were never prose</td></tr><tr><td>A folder the system will not let Leathercase read</td><td>Skipped, so one locked folder does not stop the rest</td></tr></tbody></table><p>Links to folders (shortcuts, symbolic links) are followed when they lead somewhere inside the home, and never out of it or round a loop.</p><h2 id="markdown" tabindex="-1">Markdown <a class="header-anchor" href="#markdown" aria-label="Permalink to &quot;Markdown&quot;">​</a></h2><p>A Markdown note is Leathercase&#39;s native format, and the one the plugin&#39;s writers and Obsidian users already have.</p><ul><li><strong>Front matter</strong> is read when it is there: the block between two <code>---</code> lines at the top. Leathercase reads plain values, quoted strings and lists, inline (<code>[a, b]</code>) or one per line. Nested maps are kept as text and ignored. Nothing in it is required. <a href="/guide/reference/front-matter">Front matter</a> lists every key Leathercase reads.</li><li><strong>Headings</strong> split the note into scenes. Every heading, of any level from <code>#</code> to <code>######</code>, starts a scene that runs to the next heading. Prose before the first heading is a scene too, named after the file. A heading with no prose under it is a scene planned, not yet written.</li><li><strong>Links</strong> are read both ways: <code>[[wiki links]]</code>, <code>[[Note#Heading]]</code>, and ordinary Markdown links to other notes. They resolve the way Obsidian resolves them, by file name first.</li><li><strong>Comments</strong> are your asides and are never prose: Obsidian&#39;s <code>%% comment %%</code> and HTML&#39;s <code>&lt;!-- comment --&gt;</code>. A heading inside a comment is not a scene. A tagged comment such as <code>%% TODO: check the tide %%</code> shows on the manuscript; see <a href="/guide/guide/comments">Comments and word lists</a>.</li><li><strong>Code fences</strong> are skipped: a <code>#</code> line inside a fence is not a heading.</li><li><strong>A <code>## Relationships</code> section</strong> (or <code>## Relationship</code>, <code>## Relations</code>, at any heading level) in a character or place note is read as ties in the Graph, with a word and no type: one <code>- [[Name]] — label</code> per line, until the next heading. Leathercase reads these lines and never writes them; ties you draw in the Graph go into Leathercase&#39;s own <code>Graph/Ties.md</code>, and lines drawn on the old story map stayed in <code>Relationships.md</code>.</li><li><strong>An <code>## Images</code> section</strong> in a note of one of the story&#39;s own kinds (a symbol, a motif) lists the images Leathercase looks for in the prose.</li></ul><p>Leathercase keeps a note&#39;s text as Windows saves it too: a byte order mark at the start and <code>\\r\\n</code> line endings read the same as anywhere else.</p><h2 id="word-docx" tabindex="-1">Word (.docx) <a class="header-anchor" href="#word-docx" aria-label="Permalink to &quot;Word (.docx)&quot;">​</a></h2><p>A Word file is read as if it were a Markdown note, from the styles you already use.</p><table tabindex="0"><thead><tr><th>In Word</th><th>Read as</th></tr></thead><tbody><tr><td>Heading 1 to Heading 6</td><td><code>#</code> to <code>######</code> headings: each one starts a scene</td></tr><tr><td>Normal paragraphs</td><td>Prose, one paragraph each</td></tr><tr><td><strong>Bold</strong> and <em>italic</em></td><td>Kept as emphasis, so the dialogue and thought lenses can read them</td></tr><tr><td>The Quote and Intense Quote styles</td><td>Block quotes</td></tr><tr><td>Lists and tables</td><td>Their text, as plain lines</td></tr><tr><td>Everything else (fonts, colours, page layout, headers, footers, images)</td><td>Dropped from the reading; never changed in the file</td></tr></tbody></table><p>So a chapter whose scenes start with Heading 1 gives one row per scene on the plot grid. A chapter with no headings at all is one scene, named after the file.</p><p>A Word file has no front matter, so a Word character note is typed by its folder (<code>Characters/</code>, <code>Places/</code> and the others) or by what you said the folder holds when you declared the story. The Salt Road shows both: its chapters in <code>Chapters/</code>, each scene a Heading 1, and its cast in <code>Characters/</code> and <code>Places/</code> as <code>.docx</code> notes.</p><p><strong>The story&#39;s name.</strong> When the Word files agree on a title in their properties (in Word, File, Info, Properties, Title), Leathercase suggests it as the story&#39;s name when you declare it. Notes about the story can carry no title; only the chapters need one.</p><h2 id="scrivener-scriv" tabindex="-1">Scrivener (.scriv) <a class="header-anchor" href="#scrivener-scriv" aria-label="Permalink to &quot;Scrivener (.scriv)&quot;">​</a></h2><p>A Scrivener project is a folder (<code>Orchard Hours.scriv</code>) with a binder file and one RTF file per text. Leathercase reads the binder for the order and the titles, and each text for its words.</p><ul><li><strong>Each text item is one note</strong>, at a path made from its place in the binder: <code>Orchard Hours.scriv/Manuscript/01 Friday/01 First Light.md</code>. The <code>.md</code> is Leathercase&#39;s own name for it; nothing is written to disk.</li><li><strong>The Draft</strong> (whatever you titled it, Manuscript in the sample) keeps the binder&#39;s order: its items are numbered <code>01</code>, <code>02</code> and so on, so the manuscript and the grid read in the same order Scrivener shows.</li><li><strong>Folders in the Draft</strong> become the story&#39;s parts and chapters, as folders of notes would.</li><li><strong>Research and other top-level folders</strong> keep their titles without numbers, so a <code>Characters</code> folder in Research is a folder of characters here too, and a <code>Places</code> folder is a folder of places.</li><li><strong>The Trash</strong> is left out, with everything in it: Orchard Hours&#39; discarded &quot;Old Opening&quot; never reaches a view.</li><li><strong>Each text&#39;s RTF</strong> is read as paragraphs, with italic and bold kept as emphasis. Other formatting is dropped from the reading. A text with no headings is one scene, titled with its binder title.</li><li><strong>The story&#39;s name</strong> is suggested from the project&#39;s name, <code>Orchard Hours</code>.</li></ul><p>Both Scrivener 3 projects (texts in <code>Files/Data/&lt;UUID&gt;/content.rtf</code>) and Scrivener 2 projects (<code>Files/Docs/&lt;ID&gt;.rtf</code>) are read. Opening a passage from the manuscript opens the project in Scrivener, at the project rather than at the line, since Scrivener takes no line from outside.</p><div class="warning custom-block"><p class="custom-block-title">Keep Scrivener&#39;s own sync in mind</p><p>Scrivener writes its project while it is open. Leathercase reads what is on disk, so a scene appears after Scrivener saves it. Leathercase never writes inside a <code>.scriv</code> project.</p></div><h2 id="fountain" tabindex="-1">Fountain <a class="header-anchor" href="#fountain" aria-label="Permalink to &quot;Fountain&quot;">​</a></h2><p><a href="https://fountain.io" target="_blank" rel="noreferrer">Fountain</a> is the plain-text screenplay format. Leathercase reads it as a screenplay, not as prose with odd capitals.</p><table tabindex="0"><thead><tr><th>In the script</th><th>Read as</th></tr></thead><tbody><tr><td>The title page (<code>Title:</code>, <code>Credit:</code>, <code>Author:</code> lines at the top)</td><td>The script&#39;s properties; a lone script&#39;s title is suggested as the story&#39;s name</td></tr><tr><td><code>#</code>, <code>##</code>, <code>###</code> sections</td><td>Scenes at their depth: acts and sequences</td></tr><tr><td>Sluglines (<code>INT. LIGHTHOUSE - NIGHT</code>)</td><td>Scenes, one level below the deepest section; the place, <code>Lighthouse</code>, joins the cast of places</td></tr><tr><td>Character cues (<code>NORA (V.O.)</code>)</td><td>The speaker, <code>Nora</code>, joins the cast and is present in that scene; extensions and the dual-dialogue mark <code>^</code> are not part of the name</td></tr><tr><td>Action, dialogue, lyrics, centred text</td><td>The scene&#39;s prose</td></tr><tr><td>Parentheticals, transitions, page breaks</td><td>Read for the structure, not counted as prose</td></tr><tr><td>Synopses (<code>= ...</code>), boneyard (<code>/* ... */</code>), notes (<code>[[ ... ]]</code>)</td><td>Your asides, never prose</td></tr></tbody></table><p>A <code>.fountain</code> file is the story&#39;s prose by its format: it needs no folder or type to make scenes. The Night Sleeper in the sample library is one <code>.fountain</code> file with a title page, three <code>#</code> acts, sluglines, cues and synopses.</p><p>Exporting a Fountain story can give back the script exactly as written, joined in order; see <a href="/guide/guide/export">Export</a>.</p><h2 id="obsidian-vaults" tabindex="-1">Obsidian vaults <a class="header-anchor" href="#obsidian-vaults" aria-label="Permalink to &quot;Obsidian vaults&quot;">​</a></h2><p>An Obsidian vault is a folder of Markdown notes, so Leathercase reads it as Markdown. Two things are different when the story sits inside a vault Obsidian knows on this computer:</p><ul><li><strong>Settings, Sources</strong> names the source <strong>Obsidian</strong> instead of <strong>Markdown</strong>.</li><li><strong>Opening a passage</strong> from the manuscript opens Obsidian at the scene&#39;s heading. With the Advanced URI community plugin turned on in that vault, it opens at the line.</li></ul><p>To find the vault, Leathercase reads Obsidian&#39;s own list of vaults on this computer and the vault&#39;s list of community plugins. It reads them and never changes them. The <code>.obsidian</code> folder itself is hidden, so nothing in it is read as a note.</p><p>Notes and front matter written for the Creative Writer plugin keep working: <code>creative-writer: false</code>, <code>story: true</code>, <code>writing-target</code>, <code>type:</code>, <code>aliases:</code> and the rest. See <a href="/guide/reference/front-matter">Front matter</a> for the differences.</p><h2 id="output-files-of-other-writing-software" tabindex="-1">Output files of other writing software <a class="header-anchor" href="#output-files-of-other-writing-software" aria-label="Permalink to &quot;Output files of other writing software&quot;">​</a></h2><p>Leathercase reads the files other writing apps leave on disk in the formats above, and nothing else:</p><table tabindex="0"><thead><tr><th>App</th><th>What Leathercase reads</th></tr></thead><tbody><tr><td>Obsidian, iA Writer, Typora, Ulysses (exported), Bear (exported), any text editor</td><td>Their <code>.md</code> files</td></tr><tr><td>Microsoft Word, LibreOffice Writer, Google Docs (downloaded as <code>.docx</code>), Pages (exported as <code>.docx</code>)</td><td>Their <code>.docx</code> files</td></tr><tr><td>Scrivener 2 and 3</td><td>The <code>.scriv</code> project</td></tr><tr><td>Highland, Fade In, Slugline, Beat, WriterDuet (exported), any text editor</td><td>Their <code>.fountain</code> files</td></tr><tr><td>Final Draft</td><td>Not read directly; export the script as Fountain</td></tr></tbody></table><p>An app that keeps its writing inside a database or a single proprietary file (Ulysses&#39; library, Final Draft&#39;s <code>.fdx</code>) has to export first. Leathercase reads the export; when you export again, Leathercase reads the new file the next time it looks.</p><h2 id="when-files-change" tabindex="-1">When files change <a class="header-anchor" href="#when-files-change" aria-label="Permalink to &quot;When files change&quot;">​</a></h2><p>Leathercase watches each open story&#39;s folder. A save in your writing app shows in Leathercase within moments, and the title bar says when the story was last read. On a disk that cannot report saves (some network and sync drives), Leathercase looks every few seconds instead and says so. If the folder cannot be read at all, the views keep the last reading and the title bar says the folder is lost. See <a href="/guide/guide/desk">The Desk</a> for the heartbeat line.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/how-a-story-is-read">How a story is read</a>: prose, the cast, plans, unsorted files</li><li><a href="/guide/reference/front-matter">Front matter</a>: every key Leathercase reads</li><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li><li><a href="/guide/guide/declare-a-story">Declaring a story</a></li></ul>',47)])])}const g=t(d,[["render",i]]);export{u as __pageData,g as default};
